#include <cstddef>
#include <cstdint>
extern "C" std::int64_t nagel_schrekenberg(const std::int64_t*v,std::size_t n,std::uint8_t*out,std::size_t cap){if(!v||n<5||v[0]<2||v[0]>32||v[1]<0||v[1]>16||v[2]<0||v[2]>5||n!=static_cast<std::size_t>(v[0])+3)return -1;auto cells=static_cast<std::size_t>(v[0]),steps=static_cast<std::size_t>(v[1]);int row[32],next[32],moved[32];for(std::size_t i=0;i<cells;i++){if(v[i+3]<-1||v[i+3]>5)return -1;row[i]=static_cast<int>(v[i+3]);}auto need=cells*(steps+1);if(need>cap||(need&&!out))return -2;std::size_t p=0;for(std::size_t j=0;j<cells;j++)out[p++]=static_cast<std::uint8_t>(row[j]+1);for(std::size_t t=0;t<steps;t++){for(std::size_t i=0;i<cells;i++){next[i]=-1;if(row[i]!=-1){std::size_t d=0,j=i+1;for(;j<cells;j++){if(row[j]!=-1)break;++d;}if(j==cells)for(j=0;j<cells;j++){if(row[j]!=-1)break;++d;}int speed=row[i]+1;if(speed>v[2])speed=static_cast<int>(v[2]);if(speed>static_cast<int>(d)-1)speed=static_cast<int>(d)-1;next[i]=speed;}}for(std::size_t j=0;j<cells;j++)moved[j]=-1;for(std::size_t i=0;i<cells;i++)if(next[i]!=-1)moved[(i+static_cast<std::size_t>(next[i]))%cells]=next[i];for(std::size_t j=0;j<cells;j++){row[j]=moved[j];out[p++]=static_cast<std::uint8_t>(row[j]+1);}}return static_cast<std::int64_t>(p);}
